        <ul class="lb-mleg"><li><b data-i18n="kb.lmb"></b><span data-i18n="kb.fire"></span></li><li><b data-i18n="kb.rmb"></b><span data-i18n="kb.aim"></span></li><li><b data-i18n="kb.mmb"></b><span data-i18n="kb.wheel"></span></li></ul>
